CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, verified boolean NOT NULL DEFAULT false, global_role text, mfa_secret text, mfa_enabled boolean NOT NULL DEFAULT false, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), org_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL DEFAULT 'owner', UNIQUE(user_id,org_id));
CREATE TABLE sessions(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), mfa_verified boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_tokens(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES organizations(id), kind text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft', data jsonb NOT NULL DEFAULT '{}', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX records_scope ON records(org_id,kind);
CREATE TABLE services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, category text NOT NULL, description text NOT NULL, pricing_model text NOT NULL DEFAULT 'quote', amount bigint NOT NULL DEFAULT 0 CHECK(amount>=0), currency text NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')), data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES organizations(id), user_id uuid REFERENCES users(id), title text NOT NULL, email text NOT NULL, brief text NOT NULL, status text NOT NULL DEFAULT 'new', data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), lead_id uuid REFERENCES leads(id), title text NOT NULL, version int NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','accepted','rejected','superseded')), currency text NOT NULL DEFAULT 'INR', lines jsonb NOT NULL, subtotal bigint NOT NULL CHECK(subtotal>=0), tax bigint NOT NULL DEFAULT 0 CHECK(tax>=0), discount bigint NOT NULL DEFAULT 0 CHECK(discount>=0), total bigint NOT NULL CHECK(total>=0), terms text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), quote_id uuid UNIQUE REFERENCES quotes(id), title text NOT NULL, status text NOT NULL DEFAULT 'awaiting_payment', currency text NOT NULL, total bigint NOT NULL CHECK(total>=0), paid bigint NOT NULL DEFAULT 0 CHECK(paid>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), order_id uuid UNIQUE NOT NULL REFERENCES orders(id), terms text NOT NULL, quote_snapshot jsonb NOT NULL, accepted_by uuid NOT NULL REFERENCES users(id), accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), order_id uuid UNIQUE REFERENCES orders(id), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'planning', health text NOT NULL DEFAULT 'on_track', due_date date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE milestones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, status text NOT NULL DEFAULT 'planned', weight int NOT NULL DEFAULT 1 CHECK(weight>0), position int NOT NULL DEFAULT 0, due_date date);
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid NOT NULL REFERENCES projects(id), milestone_id uuid REFERENCES milestones(id), parent_id uuid REFERENCES tasks(id), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'todo' CHECK(status IN('todo','doing','blocked','done')), assignee_id uuid REFERENCES users(id), due_date date, internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid REFERENCES projects(id), title text NOT NULL, kind text NOT NULL DEFAULT 'project', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), conversation_id uuid NOT NULL REFERENCES conversations(id), user_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE read_states(user_id uuid NOT NULL REFERENCES users(id), conversation_id uuid NOT NULL REFERENCES conversations(id), read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,conversation_id));
CREATE TABLE files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid REFERENCES projects(id), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, mime text NOT NULL, size bigint NOT NULL, storage_key text NOT NULL UNIQUE, sha256 text NOT NULL, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid NOT NULL REFERENCES projects(id), milestone_id uuid REFERENCES milestones(id), title text NOT NULL, note text NOT NULL, file_ids uuid[] NOT NULL DEFAULT '{}', version int NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','revision_requested','approved')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), delivery_id uuid NOT NULL REFERENCES deliveries(id), user_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK(decision IN('approved','revision_requested')), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id), number text NOT NULL UNIQUE, currency text NOT NULL, total bigint NOT NULL CHECK(total>=0), paid bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'issued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id), invoice_id uuid REFERENCES invoices(id), amount bigint NOT NULL CHECK(amount>0), currency text NOT NULL, provider text NOT NULL, provider_ref text NOT NULL UNIQUE, idempotency_key text NOT NULL UNIQUE, kind text NOT NULL DEFAULT 'payment', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), payment_id uuid NOT NULL REFERENCES payments(id), amount bigint NOT NULL CHECK(amount>0), reason text NOT NULL, status text NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id), project_id uuid REFERENCES projects(id), title text NOT NULL, body text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES organizations(id), user_id uuid REFERENCES users(id), title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient text NOT NULL, template text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY, org_id uuid REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action text NOT NULL, resource text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_path text NOT NULL UNIQUE, source_hash text NOT NULL UNIQUE, metadata jsonb NOT NULL, status text NOT NULL DEFAULT 'needs_review', featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_thread ON messages(conversation_id,created_at);
CREATE INDEX audit_scope ON audit_log(org_id,created_at);
CREATE INDEX notifications_scope ON notifications(org_id,user_id);
